//! A fixed-capacity LRU cache with O(1) expected time per operation.
//!
//! Entries live in a slab of nodes linked into an intrusive doubly linked
//! recency list; a hash map indexes the slab by key. Keys and values are
//! borrowed slices, so the cache never copies the data it stores.

use std::collections::HashMap;
use std::hash::{BuildHasherDefault, Hasher};

/// Sentinel index meaning "no node".
const NIL: usize = usize::MAX;

#[derive(Debug)]
struct Node<'a> {
    key: &'a [u8],
    value: &'a [u8],
    /// Towards the more recently used end.
    prev: usize,
    /// Towards the less recently used end.
    next: usize,
}

/// 64-bit FNV-1a: fast for the short keys this cache stores.
#[derive(Debug)]
pub struct FnvHasher(u64);

impl Default for FnvHasher {
    fn default() -> Self {
        Self(0xcbf2_9ce4_8422_2325)
    }
}

impl Hasher for FnvHasher {
    fn write(&mut self, bytes: &[u8]) {
        for &b in bytes {
            self.0 ^= u64::from(b);
            self.0 = self.0.wrapping_mul(0x0000_0100_0000_01b3);
        }
    }

    fn finish(&self) -> u64 {
        self.0 ^ (self.0 >> 29)
    }
}

type FnvBuildHasher = BuildHasherDefault<FnvHasher>;

#[derive(Debug)]
pub struct LruCache<'a> {
    index: HashMap<&'a [u8], usize, FnvBuildHasher>,
    nodes: Vec<Node<'a>>,
    free: Vec<usize>,
    /// Most recently used node.
    head: usize,
    /// Least recently used node.
    tail: usize,
    capacity: usize,
}

impl<'a> LruCache<'a> {
    /// Creates an empty cache holding at most `capacity` keys (minimum 1).
    ///
    /// `expected` is a hint for how many entries to preallocate.
    pub fn with_capacity(capacity: usize, expected: usize) -> Self {
        let capacity = capacity.max(1);
        let reserve = expected.min(capacity);
        Self {
            index: HashMap::with_capacity_and_hasher(reserve, FnvBuildHasher::default()),
            nodes: Vec::with_capacity(reserve),
            free: Vec::new(),
            head: NIL,
            tail: NIL,
            capacity,
        }
    }

    /// Number of keys currently held.
    pub fn len(&self) -> usize {
        self.index.len()
    }

    /// Looks up `key`, marking it most recently used on a hit.
    pub fn get(&mut self, key: &[u8]) -> Option<&'a [u8]> {
        let i = *self.index.get(key)?;
        self.touch(i);
        Some(self.nodes[i].value)
    }

    /// Inserts or overwrites `key`, making it most recently used and
    /// evicting the least recently used key if the cache overflows.
    pub fn set(&mut self, key: &'a [u8], value: &'a [u8]) {
        if let Some(&i) = self.index.get(key) {
            self.nodes[i].value = value;
            self.touch(i);
            return;
        }

        if self.len() == self.capacity {
            self.evict_lru();
        }

        let node = Node { key, value, prev: NIL, next: NIL };
        let i = match self.free.pop() {
            Some(i) => {
                self.nodes[i] = node;
                i
            }
            None => {
                self.nodes.push(node);
                self.nodes.len() - 1
            }
        };
        self.index.insert(key, i);
        self.push_front(i);
    }

    /// Removes `key`, returning whether it was present.
    pub fn remove(&mut self, key: &[u8]) -> bool {
        match self.index.remove(key) {
            Some(i) => {
                self.release(i);
                true
            }
            None => false,
        }
    }

    fn evict_lru(&mut self) {
        let i = self.tail;
        if i != NIL {
            self.index.remove(self.nodes[i].key);
            self.release(i);
        }
    }

    /// Unlinks node `i` and returns its slot to the free list.
    fn release(&mut self, i: usize) {
        self.unlink(i);
        self.free.push(i);
    }

    fn touch(&mut self, i: usize) {
        if self.head != i {
            self.unlink(i);
            self.push_front(i);
        }
    }

    fn unlink(&mut self, i: usize) {
        let Node { prev, next, .. } = self.nodes[i];
        match prev {
            NIL => self.head = next,
            p => self.nodes[p].next = next,
        }
        match next {
            NIL => self.tail = prev,
            n => self.nodes[n].prev = prev,
        }
    }

    fn push_front(&mut self, i: usize) {
        let old_head = self.head;
        let node = &mut self.nodes[i];
        node.prev = NIL;
        node.next = old_head;
        match old_head {
            NIL => self.tail = i,
            h => self.nodes[h].prev = i,
        }
        self.head = i;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn evicts_least_recently_used() {
        let mut c = LruCache::with_capacity(2, 0);
        c.set(b"a", b"1");
        c.set(b"b", b"2");
        assert_eq!(c.get(b"a"), Some(&b"1"[..]));
        c.set(b"c", b"3");
        assert_eq!(c.get(b"b"), None);
        assert_eq!(c.len(), 2);
    }

    #[test]
    fn overwrite_refreshes_recency() {
        let mut c = LruCache::with_capacity(2, 0);
        c.set(b"a", b"1");
        c.set(b"b", b"2");
        c.set(b"a", b"9");
        c.set(b"c", b"3");
        assert_eq!(c.get(b"a"), Some(&b"9"[..]));
        assert_eq!(c.get(b"b"), None);
    }

    #[test]
    fn remove_reports_presence_and_reuses_slots() {
        let mut c = LruCache::with_capacity(3, 0);
        c.set(b"x", b"1");
        assert!(c.remove(b"x"));
        assert!(!c.remove(b"x"));
        assert_eq!(c.len(), 0);
        c.set(b"y", b"2");
        assert_eq!(c.nodes.len(), 1);
        assert_eq!(c.get(b"y"), Some(&b"2"[..]));
    }
}

//! `lru` — simulate an LRU cache driven by commands on standard input.
//!
//! The first line holds the capacity; each later line is one of
//! `SET <key> <value>`, `GET <key>`, `DEL <key>` or `SIZE`. Malformed lines
//! are ignored. The whole input is read at once and the cache borrows keys
//! and values straight from that buffer.

mod cache;

use std::io::{self, Read, Write};
use std::process::ExitCode;

use cache::LruCache;

const MAX_CAPACITY: i64 = 1_000_000;
/// Longest key or value accepted; longer tokens make the command a no-op.
const MAX_TOKEN_LEN: usize = 255;

/// Parses the capacity line the way C's `strtol` would: optional leading
/// whitespace and sign, then as many digits as are present. The result is
/// clamped into `1..=MAX_CAPACITY`.
fn parse_capacity(line: &[u8]) -> usize {
    // The reference implementation only ever looked at the first 31 bytes.
    let line = &line[..line.len().min(31)];
    let start = line
        .iter()
        .position(|b| !matches!(b, b' ' | b'\t' | b'\n' | b'\x0b' | b'\x0c' | b'\r'))
        .unwrap_or(line.len());
    let rest = &line[start..];

    let value = match rest.split_first() {
        Some((b'-', digits)) => -digits_value(digits),
        Some((b'+', digits)) => digits_value(digits),
        _ => digits_value(rest),
    };
    value.clamp(1, MAX_CAPACITY) as usize
}

/// Value of the leading decimal digits, saturating well above the clamp range.
fn digits_value(s: &[u8]) -> i64 {
    s.iter()
        .take_while(|b| b.is_ascii_digit())
        .fold(0i64, |acc, &d| (acc * 10 + i64::from(d - b'0')).min(MAX_CAPACITY + 1))
}

/// Strips a single trailing carriage return.
fn trim_cr(line: &[u8]) -> &[u8] {
    line.strip_suffix(b"\r").unwrap_or(line)
}

fn write_line(out: &mut Vec<u8>, bytes: &[u8]) {
    out.extend_from_slice(bytes);
    out.push(b'\n');
}

fn run_command<'a>(cache: &mut LruCache<'a>, out: &mut Vec<u8>, line: &'a [u8]) {
    let mut tokens = line.split(|&b| b == b' ').filter(|t| !t.is_empty());
    let Some(cmd) = tokens.next() else { return };

    if cmd == b"SIZE" {
        write_line(out, cache.len().to_string().as_bytes());
        return;
    }
    let Some(key) = tokens.next().filter(|k| k.len() <= MAX_TOKEN_LEN) else {
        return;
    };

    match cmd {
        b"GET" => write_line(out, cache.get(key).unwrap_or(b"NULL")),
        b"DEL" => write_line(out, if cache.remove(key) { b"1" } else { b"0" }),
        b"SET" => {
            if let Some(value) = tokens.next().filter(|v| v.len() <= MAX_TOKEN_LEN) {
                cache.set(key, value);
            }
        }
        _ => {}
    }
}

fn run(input: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    if input.is_empty() {
        return out;
    }

    let mut lines = input.split(|&b| b == b'\n').map(trim_cr);
    let capacity = parse_capacity(lines.next().unwrap_or_default());

    // Every SET occupies one line, so the remaining line count bounds the
    // number of entries the cache can ever hold.
    let remaining_lines = input.iter().filter(|&&b| b == b'\n').count();
    let mut cache = LruCache::with_capacity(capacity, remaining_lines);

    for line in lines {
        run_command(&mut cache, &mut out, line);
    }
    out
}

fn main() -> ExitCode {
    let mut input = Vec::new();
    if let Err(err) = io::stdin().lock().read_to_end(&mut input) {
        eprintln!("lru: read error: {err}");
        return ExitCode::FAILURE;
    }

    let output = run(&input);
    let mut stdout = io::stdout().lock();
    if let Err(err) = stdout.write_all(&output).and_then(|()| stdout.flush()) {
        eprintln!("lru: write error: {err}");
        return ExitCode::FAILURE;
    }
    ExitCode::SUCCESS
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn spec_example() {
        let input = b"2\nSET a 1\nSET b 2\nGET a\nSET c 3\nGET b\nSIZE\n";
        assert_eq!(run(input), b"1\nNULL\n2\n");
    }

    #[test]
    fn capacity_parsing_mirrors_strtol() {
        assert_eq!(parse_capacity(b"  42abc"), 42);
        assert_eq!(parse_capacity(b"+7"), 7);
        assert_eq!(parse_capacity(b"-5"), 1);
        assert_eq!(parse_capacity(b"junk"), 1);
        assert_eq!(parse_capacity(b"99999999999999999999"), 1_000_000);
    }

    #[test]
    fn tolerates_crlf_and_missing_final_newline() {
        assert_eq!(run(b"1\r\nSET a 1\r\nGET a"), b"1\n");
    }
}
